const milestone=(title,instructions,commands,expected,verification)=>({title,instructions,commands,expected,verification});
export const projects=[
{id:'container-api',title:'Project 1 · Build and observe a containerized API',level:'Foundation → intermediate',prerequisites:['linux','git','testing','containers','databases','observability'],goal:'Run real code, verify HTTP and database behavior, inspect container health and prove a local backup is readable.',environment:'Python 3 and Docker on your own disposable machine/server. Registry pulls use network and storage. No cloud account or paid API is required.',files:['app.py','test_app.py','Dockerfile'],milestones:[
milestone('Test the real application','From the repository root, enter the supplied example directory. Its tests use a temporary database and loopback HTTP server.','cd dist/projects/learning-app\npython3 -m unittest -v test_app.py','Four integration tests pass, including database data, health, metrics and 404.','Record the command, test count and one behavior each test proves.'),
milestone('Build, run and inspect','Stay in dist/projects/learning-app. The container requires APP_MESSAGE. Its named volume is used only for this exercise.','docker build -t universe-learning-app:lab .\ndocker run -d --name universe-project-api -e APP_MESSAGE=hello-from-docker -p 127.0.0.1:18083:8080 --mount source=universe-project-data,target=/data universe-learning-app:lab\ncurl --fail http://127.0.0.1:18083/health\ncurl --fail http://127.0.0.1:18083/products\ncurl --fail http://127.0.0.1:18083/metrics\ndocker inspect --format "{{.State.Health.Status}}" universe-project-api','HTTP JSON and a metrics sample. Health may initially be starting; check again after its health interval.','Record the host/container port mapping, runtime user, health result and product row.'),
milestone('Validate a database backup','Use the SQLite backup API inside the disposable container and read the backup row. This does not emulate production recovery performance.',`docker exec universe-project-api python -c "import sqlite3; a=sqlite3.connect('/data/products.db'); b=sqlite3.connect('/data/backup.db'); a.backup(b); print(b.execute('SELECT * FROM products').fetchall()); a.close(); b.close()"`,'The backup contains product ID 1 and its expected name.','Record backup creation, data verification and what this toy test cannot prove about production RPO/RTO.')],cleanup:'docker rm -f universe-project-api\n# After you no longer need the disposable database and backup:\ndocker volume rm universe-project-data',limits:'Python’s http.server is for this learning example. The metrics endpoint exposes one availability marker, not a full observability platform. This is not a production deployment template.'},
{id:'kubernetes-recovery',title:'Project 2 · Deploy, break and recover Kubernetes',level:'Intermediate → advanced',prerequisites:['containers','kubernetes','releases','incidents'],goal:'Load a local image, deploy two replicas and a Service, remove required configuration, inspect the failed rollout, then restore and verify.',environment:'Docker, kind and kubectl. Requires capacity for a local Kubernetes cluster and image downloads. All mutation commands explicitly target kind-universe-project.',files:['app.py','Dockerfile','k8s.yaml'],milestones:[
milestone('Create the disposable deployment','Build from the supplied project directory. No cloud registry or cluster is required.','cd dist/projects/learning-app\ndocker build -t universe-learning-app:lab .\nkind create cluster --name universe-project\nkind load docker-image universe-learning-app:lab --name universe-project\nkubectl --context kind-universe-project apply -f k8s.yaml\nkubectl --context kind-universe-project rollout status deployment/universe-learning-app --timeout=120s\nkubectl --context kind-universe-project get pods,service -l app=universe-learning-app\nkubectl --context kind-universe-project get endpointslices -l kubernetes.io/service-name=universe-learning-app','Two ready Pods. Query the Service by name if its metadata does not match a label filter.','Record Deployment desired/ready replicas and how the Service selects Pod labels.'),
milestone('Inspect a controlled failed change','Remove the required APP_MESSAGE variable from this disposable Deployment. This creates a bad candidate rollout; healthy old replicas can continue serving depending on rollout state.','kubectl --context kind-universe-project set env deployment/universe-learning-app APP_MESSAGE-\nkubectl --context kind-universe-project get pods -l app=universe-learning-app\n# Identify a failing NEW pod name from the output, then replace NEW_POD below:\nkubectl --context kind-universe-project describe pod NEW_POD\nkubectl --context kind-universe-project logs NEW_POD --previous','The new process fails because APP_MESSAGE is missing. Previous logs are available after a restart; use current logs first if needed.','Record the actual failing Pod name, relevant event/log and why adding replicas would not fix missing configuration.'),
milestone('Recover and verify','Undo the latest Deployment revision, then verify the user path through a local port-forward.','kubectl --context kind-universe-project rollout undo deployment/universe-learning-app\nkubectl --context kind-universe-project rollout status deployment/universe-learning-app --timeout=120s\nkubectl --context kind-universe-project port-forward service/universe-learning-app 18084:80\n# In a second terminal:\ncurl --fail http://127.0.0.1:18084/health\ncurl --fail http://127.0.0.1:18084/products','The rollback reaches readiness and both endpoints return expected content.','Record rollback result, endpoint result and the prevention change you would review.')],cleanup:'Stop port-forward with Ctrl+C.\nkind delete cluster --name universe-project',limits:'Each Pod uses its own disposable SQLite file. This demonstrates configuration and routing, not a shared production database or durable multi-replica storage. Port-forward is not an Ingress replacement.'},
{id:'secure-delivery',title:'Project 3 · Verify and review a release candidate',level:'Intermediate → advanced',prerequisites:['cicd','artifacts','devsecops','identity','documentation'],goal:'Connect real tests and a container smoke check with source/artifact traceability, a scan review and a documented release decision.',environment:'Local Git, Docker and optional Trivy. Hosted CI requires your own disposable GitHub repository and runner availability; do not upload credentials.',files:['app.py','test_app.py','Dockerfile','ci-example.yml'],milestones:[
milestone('Review the candidate locally','Run tests and build once. Keep the local image identifier with the source revision. This local image ID is not automatically a pushed registry manifest digest.','cd dist/projects/learning-app\npython3 -m unittest -v test_app.py\ndocker build -t universe-learning-app:candidate .\ndocker image inspect universe-learning-app:candidate --format "{{.Id}}"\ngit rev-parse HEAD','Passing tests, a local image content identifier and a source SHA.','Explain local image ID versus registry digest, and identify the exact files used.'),
milestone('Run a real scan and interpret it','Install Trivy using its official documentation if you want to execute this optional scan. The database download and current findings depend on your environment. Do not invent a clean result.','trivy image --scanners vuln --severity HIGH,CRITICAL universe-learning-app:candidate','A dated report of actual findings or no findings, with scanner version.','Record one finding and remediation decision, or the scope/limits of an actual no-findings result.'),
milestone('Connect CI and release evidence','For hosted practice, copy the supplied app.py, test_app.py and Dockerfile into a separate disposable repository. Copy ci-example.yml to .github/workflows/ci.yml. The workflow runs tests, builds, smoke-tests and cleans up; it does not deploy production.','Review the Actions run for the exact commit. Record tests, build result, smoke-test outcome and the local scan evidence separately.','A real workflow result when you execute it in your repository, plus a go/no-go release note.','State which checks actually ran, which were skipped, any accepted risk and why a production release would or would not be approved.')],cleanup:'The example workflow removes its disposable container. Remove only your optional local candidate image if you no longer need it: docker image rm universe-learning-app:candidate',limits:'The example workflow does not claim signing, SBOM verification, a registry push, DAST or production deployment. The course explains these controls; adding them requires a separate reviewed implementation.'}
];
